package dev.crowncinder.world;
import dev.crowncinder.item.ModItems;import net.minecraft.block.Block;import net.minecraft.block.Blocks;import net.minecraft.entity.EntityType;import net.minecraft.entity.passive.VillagerEntity;import net.minecraft.item.ItemStack;import net.minecraft.server.world.ServerWorld;import net.minecraft.text.Text;import net.minecraft.util.math.BlockPos;import net.minecraft.village.TradeOffer;import net.minecraft.village.VillagerData;import net.minecraft.village.VillagerProfession;import net.minecraft.village.VillagerType;
public final class NationSettlement{private NationSettlement(){}public static void build(ServerWorld w,BlockPos o,String n){Block wall=wall(n),floor=floor(n),accent=accent(n);for(int x=-18;x<=18;x++)for(int z=-12;z<=12;z++){set(w,o.add(x,0,z),(x==0||z==0)?Blocks.SMOOTH_STONE:floor);for(int y=1;y<=6;y++)set(w,o.add(x,y,z),Blocks.AIR);}house(w,o.add(-12,1,0),wall,accent);house(w,o.add(0,1,0),wall,Blocks.BARREL);house(w,o.add(12,1,0),wall,Blocks.SMITHING_TABLE);merchant(w,o.add(12,1,1),n);npc(w,o.add(0,1,1),"§b[용병단 길드] 접수원",VillagerProfession.LIBRARIAN,"guild",n,false);npc(w,o.add(-12,1,1),"§c[기사단] 기사대장",VillagerProfession.ARMORER,"captain",n,true);npc(w,o.add(-14,1,-3),"§f[검사] 순찰검사",VillagerProfession.WEAPONSMITH,"swordsman",n,true);npc(w,o.add(-10,1,-3),"§c[기사단장] "+RpgOutpost.nationName(n),VillagerProfession.ARMORER,"knight_commander",n,true);npc(w,o.add(1,1,-3),"§e[용병] 자유 용병",VillagerProfession.TOOLSMITH,"mercenary",n,true);npc(w,o.add(-1,1,-3),"§e[용병] 방패 용병",VillagerProfession.LEATHERWORKER,"mercenary",n,true);npc(w,o.add(13,1,1),"§a[국가] 서기관",VillagerProfession.CARTOGRAPHER,"steward",n,false);}private static void house(ServerWorld w,BlockPos c,Block wall,Block accent){for(int x=-3;x<=3;x++)for(int z=-4;z<=4;z++){for(int y=0;y<=4;y++)set(w,c.add(x,y,z),y==0?Blocks.SMOOTH_STONE:(x==-3||x==3||z==-4||z==4)?wall:Blocks.AIR);set(w,c.add(x,5,z),Blocks.STONE_BRICK_SLAB);}set(w,c.add(0,1,-4),Blocks.AIR);set(w,c.add(0,2,-4),Blocks.AIR);set(w,c.add(0,1,2),accent);}private static void merchant(ServerWorld w,BlockPos p,String n){VillagerEntity v=npc(w,p,"§6[상점] "+RpgOutpost.nationName(n)+" 무기상",VillagerProfession.WEAPONSMITH,"merchant",n,false);if(v!=null){v.getOffers().add(new TradeOffer(new ItemStack(ModItems.SILVER_COIN,4),new ItemStack(ModItems.LONGSWORD),999,0,0));v.getOffers().add(new TradeOffer(new ItemStack(ModItems.SILVER_COIN,6),new ItemStack(ModItems.RAPIER),999,0,0));v.getOffers().add(new TradeOffer(new ItemStack(ModItems.SILVER_COIN,8),new ItemStack(ModItems.KATANA),999,0,0));v.getOffers().add(new TradeOffer(new ItemStack(ModItems.SILVER_COIN,12),new ItemStack(ModItems.KNIGHT_BLADE),999,0,0));}}private static VillagerEntity npc(ServerWorld w,BlockPos p,String name,VillagerProfession prof,String role,String n,boolean moving){VillagerEntity v=EntityType.VILLAGER.create(w);if(v==null)return null;v.setVillagerData(new VillagerData(VillagerType.PLAINS,prof,5));v.refreshPositionAndAngles(p.getX()+.5,p.getY(),p.getZ()+.5,0,0);v.setCustomName(Text.literal(name));v.setCustomNameVisible(true);v.setPersistent();v.setAiDisabled(!moving);v.addCommandTag("crown_npc");v.addCommandTag("crown_role_"+role);v.addCommandTag("crown_nation_"+n);w.spawnEntity(v);return v;}private static void set(ServerWorld w,BlockPos p,Block b){w.setBlockState(p,b.getDefaultState(),3);}private static Block wall(String n){return switch(n){case"eldoria"->Blocks.DEEPSLATE_BRICKS;case"kharum"->Blocks.COBBLED_DEEPSLATE;case"sylvan"->Blocks.OAK_LOG;case"varkhan"->Blocks.BLACKSTONE;default->Blocks.STONE_BRICKS;};}private static Block floor(String n){return switch(n){case"eldoria"->Blocks.CALCITE;case"kharum"->Blocks.COBBLESTONE;case"sylvan"->Blocks.MOSS_BLOCK;case"varkhan"->Blocks.POLISHED_BLACKSTONE;default->Blocks.SMOOTH_STONE;};}private static Block accent(String n){return switch(n){case"eldoria"->Blocks.AMETHYST_BLOCK;case"kharum"->Blocks.IRON_BLOCK;case"sylvan"->Blocks.EMERALD_BLOCK;case"varkhan"->Blocks.REDSTONE_BLOCK;default->Blocks.GOLD_BLOCK;};}}
